package local.spatialclient;
import java.util.*;import java.nio.file.*;import java.util.concurrent.atomic.AtomicReference;
import net.minecraft.client.Minecraft;import net.minecraft.resources.Identifier;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.effect.MobEffectInstance;import net.minecraft.world.phys.Vec3;
import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.spell_engine.entity.*;import net.spell_engine.internals.*;import net.spell_engine.internals.target.SpellTarget;import net.spell_engine.internals.casting.SpellCast;
@Mod(value="spatial_client_probe",dist=Dist.CLIENT) public class ClassClientProbe {
 int ticks,phase,at;boolean pending;UUID target;final List<String> lines=new ArrayList<>();final AtomicReference<Throwable> error=new AtomicReference<>();
 public ClassClientProbe(){NeoForge.EVENT_BUS.addListener(this::tick);}
 void check(boolean ok,String label){lines.add((ok?"PASS ":"FAIL ")+label);if(!ok)throw new AssertionError(label);}
 void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> job){var mc=Minecraft.getInstance();pending=true;mc.getSingleplayerServer().execute(()->{try{job.accept(mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()));}catch(Throwable e){error.set(e);}finally{pending=false;}});}
 void step(){phase++;at=ticks;}
 void finish(){if(phase==99)return;phase=99;var mc=Minecraft.getInstance();try{Files.write(mc.gameDirectory.toPath().resolve("spatial-client-checks.txt"),lines);Files.writeString(mc.gameDirectory.toPath().resolve("spatial-client-result.txt"),lines.stream().anyMatch(s->s.startsWith("FAIL"))?"FAIL":"PASS");}catch(Exception ignored){}mc.stop();}
 void inputCheck()throws Exception{
  var mc=Minecraft.getInstance();mc.setScreenAndShow(null);var p=mc.player;p.zza=.8f;p.xxa=.6f;
  var method=Arrays.stream(p.getClass().getDeclaredMethods()).filter(m->m.getName().contains("tickMovement_ModifyInput")).findFirst().orElseThrow();method.setAccessible(true);method.invoke(p,new org.spongepowered.asm.mixin.injection.callback.CallbackInfo("applyInput",false));
  check(Math.abs(p.zza-.8)<.001&&Math.abs(p.xxa-.6)<.001,"Actual Better Combat client input hook preserves full movement");
 }
 void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();ticks++;if(phase==99)return;try{
  if(error.get()!=null)throw new RuntimeException(error.get());if(pending||mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;if(ticks-at>1800)throw new AssertionError("Timeout phase"+phase);
  if(phase==0){server(p->{p.removeAllEffects();p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getFoodData().setFoodLevel(20);for(int x=-3;x<=3;x++)for(int z=-3;z<=10;z++){p.level().setBlock(new net.minecraft.core.BlockPos(x,99,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);for(int y=100;y<104;y++)p.level().setBlock(new net.minecraft.core.BlockPos(x,y,z),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);}p.teleportTo(0,100,0);var e=EntityTypes.ZOMBIE.create(p.level(),EntitySpawnReason.COMMAND);e.setPos(0,100,6);e.setYHeadRot(0);e.setNoAi(true);e.setNoGravity(true);target=e.getUUID();p.level().addFreshEntity(e);p.addEffect(new MobEffectInstance(WarriorRules.effect("rogues:charge"),400));});step();return;}
  if(ticks-at<30)return;
  if(phase==1){check(ClassRework.mobile(mc.player),"Charge movement eligibility synchronized");inputCheck();server(p->{p.removeAllEffects();p.addEffect(new MobEffectInstance(WarriorRules.effect(WarriorUltimates.BERSERKER),400));});step();return;}
  if(phase==2){check(ClassRework.mobile(mc.player),"Berserker movement eligibility synchronized");inputCheck();server(p->{p.removeAllEffects();var e=(net.minecraft.world.entity.LivingEntity)p.level().getEntity(target);var h=PaladinRevamp.spell(p,"rogues:mutilate");var owner=(net.spell_engine.internals.container.SpellContainerSource.Owner)p;var old=owner.getSpellContainers();owner.setSpellContainers(new net.spell_engine.internals.container.SpellContainerSource.Result(old.activeContainer(),List.of(h),List.of(),List.of(),List.of(new net.spell_engine.internals.container.SpellContainerSource.SourcedContainer("probe",net.minecraft.world.item.ItemStack.EMPTY,new net.spell_engine.api.spell.container.SpellContainer(net.spell_engine.api.spell.container.SpellContainer.ContentType.ANY,"","",0,List.of("rogues:mutilate"))))));owner.spellModifierCache().clear();var cd=((net.spell_engine.internals.casting.SpellCaster.Player)p).getCooldownManager();cd.set(h,100);var before=p.position();SpellExecution.performSpell(p.level(),p,h,new SpellTarget.SearchResult(List.of(e),null),SpellCast.Action.RELEASE,1);check(p.position().distanceToSqr(before)<.001,"Rejected cooldown cast does not teleport");cd.reset(null);SpellExecution.performSpell(p.level(),p,h,new SpellTarget.SearchResult(List.of(e),null),SpellCast.Action.RELEASE,1);check(p.distanceTo(e)<1.2&&p.getZ()>e.getZ(),"Native Mutilate cast teleports in front of enemy");});step();return;}
  if(phase==3){check(mc.player.getZ()>6&&mc.player.getZ()<7.2,"Mutilate destination reaches client");check(!ClassRework.mobile(mc.player),"Expired movement exception clears on client");server(p->{var category=net.puffish.skillsmod.api.SkillsAPI.getCategory(Identifier.parse("skill_tree_rpgs:class_skills")).orElseThrow();category.unlock(p);category.resetSkills(p);category.setExtraPoints(p,1000);category.getSkill("ASSASSIN_ROOT_SKILL").orElseThrow().unlock(p);});step();return;}
  if(phase==4){check(ClassRework.mobile(mc.player),"Selected Assassin path enables full movement on client");inputCheck();server(p->net.puffish.skillsmod.api.SkillsAPI.getCategory(Identifier.parse("skill_tree_rpgs:class_skills")).orElseThrow().resetSkills(p));step();return;}
  if(phase==5){check(!ClassRework.mobile(mc.player),"Path reset removes movement exception");finish();}
 }catch(Throwable e){e.printStackTrace();lines.add("FAIL "+e);finish();}}
}
